import{_ as l,a0 as i,w as o,s as a,I as n,x as u,a1 as p,A as e,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Ubuntu 服务器版与桌面版有什么区别？ | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 服务器版与桌面版有什么区别？ | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 服务器版与桌面版有什么区别？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 服务器版与桌面版有什么区别？ | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20210901 Ubuntu Server vs Desktop- What-s the Difference","title":"Ubuntu 服务器版与桌面版有什么区别？","tag":"202201","desc":""},"relativePath":"202201/20210901 Ubuntu Server vs Desktop- What-s the Difference.md","filePath":"[post].md"}'),b={name:"202201/20210901 Ubuntu Server vs Desktop- What-s the Difference.md"};function d(m,t,f,U,g,T){const s=i("Link");return o(),a("div",null,[t[28]||(t[28]=n("h1",{id:"ubuntu-服务器版与桌面版有什么区别",tabindex:"-1"},[u("Ubuntu 服务器版与桌面版有什么区别？ "),n("a",{class:"header-anchor",href:"#ubuntu-服务器版与桌面版有什么区别","aria-label":"Permalink to “Ubuntu 服务器版与桌面版有什么区别？”"},"​")],-1)),t[29]||(t[29]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202201/04/122152zdqkkqqqw6cgcdcq.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=u("当你点击 ",-1)),p(s,{href:"https://ubuntu.com/"},{default:e(()=>[...t[0]||(t[0]=[u("Ubuntu 网站",-1)])]),_:1}),t[2]||(t[2]=u(" 上的下载按钮时，它会给你几个选项。其中两个分别是 Ubuntu 桌面版和 Ubuntu 服务器版。",-1))]),t[30]||(t[30]=r('<p>这可能会让新用户感到困惑。为什么会有两个（实际上是四个）？应该下载哪一个？Ubuntu 桌面版还是服务器版？它们是一样的吗？有什么区别？</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/ubuntu-server-desktop-download-800x338.webp" alt="Ubuntu 网站给了你多种选择"></p><p>我将解释 Ubuntu 的桌面版和服务器版的区别。我还会解释你应该使用哪个变体。</p><h3 id="ubuntu-桌面版与-ubuntu-服务器版" tabindex="-1">Ubuntu 桌面版与 Ubuntu 服务器版 <a class="header-anchor" href="#ubuntu-桌面版与-ubuntu-服务器版" aria-label="Permalink to “Ubuntu 桌面版与 Ubuntu 服务器版”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/ubuntu-desktop-server.png?resize=800%2C450&amp;ssl=1" alt="Ubuntu 桌面版和服务器版"></p><p>要了解 Ubuntu 桌面版和服务器版的区别，你应该了解桌面操作系统和服务器操作系统的区别。</p><h4 id="桌面操作系统" tabindex="-1">桌面操作系统 <a class="header-anchor" href="#桌面操作系统" aria-label="Permalink to “桌面操作系统”">​</a></h4><p><ruby>桌面电脑<rt>Desktop</rt></ruby>是指个人电脑（PC）。桌面电脑操作系统带有一个图形用户界面，以便用户可以使用鼠标和键盘操作。桌面电脑的主要目的是给你一个系统，可以用来浏览网页、编辑文档、查看/编辑图片和视频、编码和游戏。基本上，就是为个人、终端用户或家庭成员提供了一个通用的计算机。</p><p>我在这里使用桌面电脑这个术语，但这并不意味着它不能用于笔记本电脑。桌面电脑是个人电脑的通用术语。</p><h4 id="服务器操作系统" tabindex="-1">服务器操作系统 <a class="header-anchor" href="#服务器操作系统" aria-label="Permalink to “服务器操作系统”">​</a></h4><p>另一方面，服务器操作系统是专门为托管网站、应用程序、媒体服务器、数据库等网络服务而打造的。</p><p>通常情况下，服务器操作系统不带有图形界面。如果是基于 Linux 的操作系统，你就得通过终端的命令来使用该系统。</p>',12)),n("p",null,[t[4]||(t[4]=u("这里的好处是，服务器操作系统不需要（浪费）大量的内存和计算能力，因为它们不使用 ",-1)),p(s,{href:"https://itsfoss.com/what-is-desktop-environment/"},{default:e(()=>[...t[3]||(t[3]=[u("图形化桌面环境",-1)])]),_:1}),t[5]||(t[5]=u("。除此以外，服务器操作系统的软件包配置也不同。",-1))]),t[31]||(t[31]=r('<p>现在你对服务器和桌面的区别有了一些了解，让我们看看 Ubuntu 服务器版和桌面版的区别。</p><h4 id="用户界面" tabindex="-1">用户界面 <a class="header-anchor" href="#用户界面" aria-label="Permalink to “用户界面”">​</a></h4><p>Ubuntu 服务器版和桌面版之间最明显的区别是用户界面。</p><p>Ubuntu 桌面版的特点是采用 GNOME 桌面环境的图形化用户界面。这使得它在鼠标点击的帮助下更容易使用。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/installing-gui-ubuntu-server-gnome-desktop.png?resize=792%2C597&amp;ssl=1" alt="图为 Ubuntu GNOME 版的用户界面"></p><p>Ubuntu 服务器版采用<ruby>无头方式<rt>headless</rt></ruby>运行。你只有在登录后才会看到一个终端界面。你经常会从其他电脑上通过 SSH 来远程管理它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/system-restart-required.png?resize=800%2C469&amp;ssl=1" alt="通过 SSH 连接到远程 Ubuntu 服务器"></p><h4 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h4>',8)),n("p",null,[p(s,{href:"https://itsfoss.com/install-ubuntu/"},{default:e(()=>[...t[6]||(t[6]=[u("由于有了图形化的安装程序，将 Ubuntu 作为桌面电脑是很容易的",-1)])]),_:1}),t[7]||(t[7]=u("。你可以创建一个",-1)),t[8]||(t[8]=n("ruby",null,[u("临场 USB"),n("rt",null,"Live USB")],-1)),t[9]||(t[9]=u("，无需安装即可体验桌面版。如果你喜欢，你可以按照屏幕上的指示在几分钟内安装它。",-1))]),t[32]||(t[32]=r('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/02/installing-ubuntu.png?resize=800%2C549&amp;ssl=1" alt="通过图形化安装程序安装 Ubuntu 桌面版"></p><p>将 Ubuntu 作为服务器安装并不像桌面版那样简单。你只能使用终端界面。如果你不熟悉这个流程，即使是最简单的任务，如连接到 Wi-Fi，也可能是一个困难的任务。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/ubuntu-server-installation.png?resize=800%2C600&amp;ssl=1" alt="Ubuntu 服务器版的安装"></p><h4 id="应用程序" tabindex="-1">应用程序 <a class="header-anchor" href="#应用程序" aria-label="Permalink to “应用程序”">​</a></h4><p>在 Ubuntu 桌面版中，默认的应用程序集主要针对普通计算机用户。因此，你会发现网页浏览器、办公套件、媒体播放器、游戏等。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/gnome-app-arranger.jpg?resize=799%2C450&amp;ssl=1" alt="Ubuntu 中的应用程序"></p><p>Ubuntu 服务器版的应用程序更多的是为运行网络服务而定制的。而这还不是全部。有些应用程序的配置也是不同的。以 SSH 为例。Ubuntu 服务器预设了 SSH，这样你就可以轻松地从远程系统连接到它。而在 Ubuntu 桌面版上，你必须明确启用 SSH 才行。</p><h4 id="硬件要求" tabindex="-1">硬件要求 <a class="header-anchor" href="#硬件要求" aria-label="Permalink to “硬件要求”">​</a></h4><p>由于桌面版具有图形用户界面，你需要至少 4GB 的内存来运行 Ubuntu 桌面版。磁盘空间至少要有 20GB。</p><p>这就是 Ubuntu 服务器的有趣之处。它没有图形化的界面。命令行界面不会消耗大量的系统资源。因此，你可以在 512MB 和 5GB 磁盘空间的机器上轻松运行 Ubuntu 服务器。（LCTT 译注：当然，对于服务器环境来说，内存和磁盘空间是多多益善。）</p><p>服务器上的内存和磁盘空间受制于你所运行的网络服务。如果一个网络应用需要至少 2GB 的内存，你就应该有这么多的内存。但在最简单的情况下，即使是 512MB 或 1GB 的内存也可以工作。</p><h4 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to “用途”">​</a></h4><p>这是 Ubuntu 桌面版和服务器版之间的主要区别。问问自己，你想把 Ubuntu 用于什么目的？</p><p>如果是专门用于部署网络服务，那就选择 Ubuntu 服务器。请记住，你需要有基本的 Linux 命令行知识来使用终端。</p><p>如果你想把 Ubuntu 作为像 Windows 一样的普通电脑使用，那就选择 Ubuntu 桌面版。如果你想用它来学习 Linux 命令，或用于学习的 Docker 或者甚至是简单的（但是本地的）LAMP 服务器环境，请继续使用 Ubuntu 桌面。</p><p>对于服务器来说，Ubuntu 服务器版要比 Ubuntu 桌面版好。对于常规的计算机使用，Ubuntu 桌面版是更好的选择。</p><h4 id="你应该在服务器上使用-ubuntu-桌面版还是在服务器上安装图形界面" tabindex="-1">你应该在服务器上使用 Ubuntu 桌面版还是在服务器上安装图形界面？ <a class="header-anchor" href="#你应该在服务器上使用-ubuntu-桌面版还是在服务器上安装图形界面" aria-label="Permalink to “你应该在服务器上使用 Ubuntu 桌面版还是在服务器上安装图形界面？”">​</a></h4><p>是这样的，Ubuntu 桌面版和服务器版都是 Linux，你可以用 Ubuntu 桌面版作为服务器来托管网页服务。这没问题。</p>',18)),n("p",null,[t[11]||(t[11]=u("同样地，",-1)),p(s,{href:"https://itsfoss.com/install-gui-ubuntu-server/"},{default:e(()=>[...t[10]||(t[10]=[u("你可以在 Ubuntu 服务器上安装图形界面",-1)])]),_:1}),t[12]||(t[12]=u("，并以图形方式使用它。这也是可行的。",-1))]),t[33]||(t[33]=n("p",null,[n("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/installing-gui-ubuntu-server-gnome-desktop-greet.png?resize=798%2C600&ssl=1",alt:"Ubuntu 服务器上的 GUI 登录"})],-1)),t[34]||(t[34]=n("p",null,"但仅仅因为它可行，并不意味着你应该这么做。它违背了为服务器和桌面电脑创建不同版本的全部目的。",-1)),t[35]||(t[35]=n("p",null,"你必须付出额外的努力来将服务器版转换为桌面版，反之亦然。为什么要承受这种痛苦呢？",-1)),t[36]||(t[36]=n("p",null,"如果你使用 Ubuntu 的目的很明确，那就下载并安装合适的 Ubuntu 版本。",-1)),t[37]||(t[37]=n("p",null,"我希望这能使围绕 Ubuntu 桌面版和服务器版的选择现在更清楚一些。如果你有问题或建议，请利用评论区。",-1)),t[38]||(t[38]=n("hr",null,null,-1)),n("p",null,[t[14]||(t[14]=u("via: ",-1)),p(s,{href:"https://itsfoss.com/ubuntu-server-vs-desktop/"},{default:e(()=>[...t[13]||(t[13]=[u("https://itsfoss.com/ubuntu-server-vs-desktop/",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=u("作者：",-1)),p(s,{href:"https://itsfoss.com/author/abhishek/"},{default:e(()=>[...t[15]||(t[15]=[u("Abhishek Prakash",-1)])]),_:1}),t[20]||(t[20]=u(" 选题：",-1)),p(s,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[16]||(t[16]=[u("lujun9972",-1)])]),_:1}),t[21]||(t[21]=u(" 译者：",-1)),p(s,{href:"https://github.com/wxy"},{default:e(()=>[...t[17]||(t[17]=[u("wxy",-1)])]),_:1}),t[22]||(t[22]=u(" 校对：",-1)),p(s,{href:"https://github.com/wxy"},{default:e(()=>[...t[18]||(t[18]=[u("wxy",-1)])]),_:1})]),n("p",null,[t[25]||(t[25]=u("本文由 ",-1)),p(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[23]||(t[23]=[u("LCTT",-1)])]),_:1}),t[26]||(t[26]=u(" 原创编译，",-1)),p(s,{href:"https://linux.cn/"},{default:e(()=>[...t[24]||(t[24]=[u("Linux中国",-1)])]),_:1}),t[27]||(t[27]=u(" 荣誉推出",-1))])])}const C=l(b,[["render",d]]);e